edges = [(0,1),(1,2),(2,3),(3,4),(4,0),  # outer 5-cycle
         (5,7),(7,9),(9,6),(6,8),(8,5),  # inner pentagram
         (0,5),(1,6),(2,7),(3,8),(4,9)]  # spokes

# verify
from collections import defaultdict
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
print("degrees:", [len(adj[i]) for i in range(10)])

# girth via BFS
def girth(adj,n):
    g=float('inf')
    for s in range(n):
        dist={s:0}; parent={s:-1}
        from collections import deque
        q=deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v]=dist[u]+1; parent[v]=u; q.append(v)
                elif parent[u]!=v:
                    g=min(g,dist[u]+dist[v]+1)
    return g
print("girth:", girth(adj,10))
